// text render function starts here;
const text_container = document.querySelector('#text-container')
function textRender(text) {
    const words = text.split(' ')
    console.log(words)
    let html_codes = ''
    let i=0
    words.forEach(word => {
        html_codes += '<span class="word">'
        for(let j=0; j<word.length; j++){
             html_codes += `<span id="letter${i}" class="letter ">${word[j]}</span>`
            i++
        };
        html_codes += '</span>'

        html_codes += `<span id="letter${i}" class="space "> </span>`
        i++
    });
    text_container.innerHTML = html_codes
}

textRender(text)
//text render function ends here;